/* @ts-self-types="./number.d.ts" */
//#region src/immutable/number.ts
function add(...a) {
	let r = 0;
	for (const n of a) r += n;
	return r;
}
/** `a - b - c - ...` */
const substract = (a, ...b) => {
	for (const n of b) a -= n;
	return a;
};
/** `a * b * c * ...` */
const multiply = (a, ...b) => {
	for (const n of b) a *= n;
	return a;
};
/** `a / b / c / ...` */
const divide = (a, ...b) => {
	for (const n of b) a /= n;
	return a;
};
/** `a ** b ** c ** ...` */
const power = (a, ...b) => {
	for (const n of b) a = a ** n;
	return a;
};
/** clamp a number value between two other values */
const clamp = (n, min, max) => Math.min(max, Math.max(min, n));
//#endregion
export { add, clamp, divide, multiply, power, substract };
